CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_name TEXT NOT NULL, public_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_key_wraps (conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE, wrapped_key TEXT NOT NULL, wrapped_key_iv TEXT NOT NULL, sender_device_id TEXT NOT NULL, wrap_version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (conversation_id, device_id));
